def solve(lst):
    """Flatten a nested list, returning only integer values (excluding booleans).
    Args:
        lst (list): A possibly nested list containing integers and other elements.
    Returns:
        list: A flat list of integers in the order they appear.
    """
    result = []
    def helper(item):
        if isinstance(item, list):
            for sub in item:
                helper(sub)
        else:
            # Include only ints, but exclude booleans (bool is subclass of int)
            if isinstance(item, int) and not isinstance(item, bool):
                result.append(item)
    helper(lst)
    return result

