def solve(n):
    """Return the number of primes strictly less than n.
    Accepts int or numeric types that can be safely converted to int.
    For non-positive or non-numeric inputs, returns 0.
    Uses Sieve of Eratosthenes with a bytearray for efficiency.
    """
    # Convert to integer if possible
    try:
        if isinstance(n, bool):
            # bool is subclass of int but not a valid count
            n = int(n)
        elif not isinstance(n, int):
            # Try to convert floats with no fractional part
            n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    limit = n - 1
