def solve(words, width):
    """Greedy word wrap.
    Pack words into lines separated by a single space. Each line's length (including the spaces
    between words) must not exceed *width*, unless a single word itself is longer than *width*;
    in that case the word occupies a line on its own, exceeding the limit.
    If *width* is non‑positive, no line can satisfy the constraint, so we return an empty list.
    """
    if width <= 0:
        return []
    if not words:
        return []
    lines = []
    cur_line = []
    cur_len = 0  # length of current line including words but not spaces
    for w in words:
        if not cur_line:
            # start a new line with this word (even if it exceeds width)
            cur_line.append(w)
            cur_len = len(w)
        else:
            # prospective length if we add this word preceded by a space
            if cur_len + 1 + len(w) <= width:
                cur_line.append(w)
                cur_len += 1 + len(w)
            else:
                # finish current line
                lines.append(' '.join(cur_line))
                # start new line with the word
                cur_line = [w]
                cur_len = len(w)
    if cur_line:
        lines.append(' '.join(cur_line))
    return lines

