    """Return length of longest strictly increasing subsequence.
    Uses patience sorting O(n log n).
    """
    import bisect
    if not isinstance(nums, list):
        return 0
    tails = []  # tails[i] is the smallest ending value of an increasing subseq of length i+1
    for x in nums:
        # only consider numeric values
        if not isinstance(x, (int, float)):
            continue
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        # for strictly increasing, we need to ensure x > tails[-1] when extending, bisect_left works because equal replaces
