def solve(n):
    """Return the number of prime numbers strictly less than n.
    Accepts int, float (treated as int if it is a whole number), or numeric strings.
    Non‑positive or non‑numeric inputs yield 0.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    # Helper to coerce to int safely
    def to_int(val):
        if isinstance(val, bool):
            return int(val)
        if isinstance(val, (int, )):
            return val
        if isinstance(val, float):
            # Only accept if it is an integer value
            if val.is_integer():
                return int(val)
            else:
                return None
        if isinstance(val, str):
            try:
                iv = int(val)
                return iv
            except Exception:
                return None
        return None

    n_int = to_int(n)
    if n_int is None or n_int <= 2:
        return 0
    limit = n_int - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    max_p = int(math.isqrt(limit))
    for p in range(2, max_p + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit + 1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

