def solve(a, x):
    """Return the leftmost insertion index for x in sorted list a.
    Uses binary search (bisect_left) without importing bisect.
    Handles empty list and works for any orderable types.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

