def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 then lowercase a-z. Negative numbers get a leading '-'.
    """
    if not isinstance(n, int) or not isinstance(b, int):
        raise TypeError("Both n and b must be integers")
    if b < 2 or b > 36:
        raise ValueError("Base must be between 2 and 36 inclusive")
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res_chars = []
    while n > 0:
        n, rem = divmod(n, b)
        res_chars.append(digits[rem])
    if neg:
        res_chars.append('-')
    return ''.join(reversed(res_chars))
